"""Extract inventory fields from an untrusted pickle WITHOUT executing code.

Interprets only data-only opcodes. Any attempt to reference a global
(GLOBAL/STACK_GLOBAL) is replaced by a marker, and REDUCE is never invoked.
"""
import io
import json
import pickletools
from pathlib import Path

SRC = Path('incoming/model.pkl')
OUT = Path('reports/model_inventory.json')


class BlockedGlobal:
    def __init__(self, module, name):
        self.module = module
        self.name = name


def safe_load(data: bytes):
    stack, marks, attempted = [], [], []
    for opcode, arg, pos in pickletools.genops(io.BytesIO(data)):
        op = opcode.name
        if op in ('PROTO', 'FRAME', 'MEMOIZE'):
            continue
        if op == 'EMPTY_DICT':
            stack.append({})
        elif op in ('SHORT_BINUNICODE', 'BINUNICODE', 'UNICODE',
                    'SHORT_BINSTRING', 'BINSTRING', 'STRING', 'BINBYTES', 'SHORT_BINBYTES'):
            stack.append(arg)
        elif op in ('BININT1', 'BININT2', 'INT'):
            stack.append(arg)
        elif op == 'EMPTY_LIST':
            stack.append([])
        elif op == 'EMPTY_TUPLE':
            stack.append(())
        elif op == 'MARK':
            marks.append(len(stack))
        elif op == 'POP':
            stack.pop()
        elif op == 'APPEND':
            item, target = stack.pop(), stack.pop()
            target.append(item)
            stack.append(target)
        elif op == 'APPENDS':
            mark = marks.pop()
            items = stack[mark:]
            del stack[mark:]
            target = stack.pop()
            target.extend(items)
            stack.append(target)
        elif op == 'SETITEMS':
            mark = marks.pop()
            pairs = stack[mark:]
            del stack[mark:]
            target = stack.pop()
            for key, value in zip(pairs[0::2], pairs[1::2]):
                target[key] = value
            stack.append(target)
        elif op == 'TUPLE1':
            stack.append((stack.pop(),))
        elif op == 'TUPLE2':
            b, a = stack.pop(), stack.pop()
            stack.append((a, b))
        elif op == 'TUPLE3':
            c, b, a = stack.pop(), stack.pop(), stack.pop()
            stack.append((a, b, c))
        elif op == 'STACK_GLOBAL':
            name, module = stack.pop(), stack.pop()
            stack.append(BlockedGlobal(module, name))
        elif op == 'GLOBAL':
            stack.append(BlockedGlobal(arg[0], arg[1]))
        elif op == 'REDUCE':
            args, callable_ = stack.pop(), stack.pop()
            if isinstance(callable_, BlockedGlobal):
                attempted.append((f"{callable_.module}.{callable_.name}", args))
                stack.append(f"<refused: {callable_.module}.{callable_.name}>")
            else:
                raise RuntimeError(f"unexpected REDUCE target: {callable_!r}")
        elif op == 'BUILD':
            state, obj = stack.pop(), stack.pop()
            if isinstance(obj, dict) and isinstance(state, dict):
                obj.update(state)
            stack.append(obj)
        elif op == 'STOP':
            break
        else:
            raise RuntimeError(f"unsupported pickle opcode: {op} at offset {pos}")
    if len(stack) != 1:
        raise RuntimeError(f"unexpected final stack size: {len(stack)}")
    return stack[0], attempted


def main():
    obj, attempted = safe_load(SRC.read_bytes())
    report = {
        'model_type': obj['model_type'],
        'protocol_version': obj['protocol_version'],
        'tensors': list(obj['tensors'].keys()),
    }
    OUT.write_text(json.dumps(report, indent=2) + '\n')
    print(json.dumps(report, indent=2))
    print('full payload keys:', sorted(obj.keys()))
    if attempted:
        print('\nBLOCKED code-execution payloads (NOT executed):')
        for name, args in attempted:
            print(' -', name, '<-', args)


if __name__ == '__main__':
    main()
EOF
